// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    Reentrancy_bonus c;
    function setUp() public { c = new Reentrancy_bonus(); }
    function testRegression_property() public {
        vm.deal(address(c), 200);

        address alice = address(0x1234);

        uint256 balanceBefore = address(c).balance;

        vm.prank(alice);
        c.getFirstWithdrawalBonus(alice);

        assertTrue(address(c).balance == balanceBefore - 100);
    }
}
